  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_visible` tinyint(1) NOT NULL DEFAULT '1',
  `public_label` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admin_user_id` int unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_delivery_hist` (`delivery_id`,`created_at`),
  CONSTRAINT `fk_delivery_hist_delivery` FOREIGN KEY (`delivery_id`) REFERENCES `deliveries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `delivery_store`;
CREATE TABLE `delivery_store` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Apni Tokri — Indore',
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `max_radius_km` decimal(8,2) NOT NULL DEFAULT '12.00',
  `timezone` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Asia/Kolkata',
  `slots_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `prep_minutes` int unsigned NOT NULL DEFAULT '45',
  `business_open` time NOT NULL DEFAULT '08:00:00',
  `business_close` time NOT NULL DEFAULT '20:00:00',
  `mixed_cart_free_rule` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'eligible_subtotal',
  `default_distance_mode` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'haversine',
  `road_distance_provider` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `road_distance_config_json` json DEFAULT NULL,
  `overlap_policy` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'reject',
  `fallback_radius_zone_id` int unsigned DEFAULT NULL,
  `require_coordinates_for_checkout` tinyint(1) NOT NULL DEFAULT '0',
  `manual_delivery_when_provider_unavailable` tinyint(1) NOT NULL DEFAULT '0',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `delivery_zones`;
CREATE TABLE `delivery_zones` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `match_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pincode_prefix',
  `match_value` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zone_kind` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pincode',
  `min_distance_km` decimal(8,2) DEFAULT NULL,
  `max_distance_km` decimal(8,2) DEFAULT NULL,
  `flat_fee` decimal(12,2) NOT NULL DEFAULT '40.00',
  `free_above` decimal(12,2) NOT NULL DEFAULT '499.00',
  `max_order_weight_kg` decimal(8,3) DEFAULT NULL,
  `eta_display` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pincode_required` tinyint(1) NOT NULL DEFAULT '0',
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `idx_delivery_zones_active` (`is_active`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `faq_categories`;
CREATE TABLE `faq_categories` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_faq_cat_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `faqs`;
CREATE TABLE `faqs` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int unsigned DEFAULT NULL,
  `question` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `idx_faqs_category` (`category_id`),
  CONSTRAINT `fk_faqs_category` FOREIGN KEY (`category_id`) REFERENCES `faq_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `inventory_movements`;
CREATE TABLE `inventory_movements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `variant_id` bigint unsigned NOT NULL,
  `change_qty` int NOT NULL,
  `qty_before` int NOT NULL,
  `qty_after` int NOT NULL,
  `reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `admin_user_id` int unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_inventory_variant_created` (`variant_id`,`created_at`),
  KEY `fk_inv_admin` (`admin_user_id`),
  CONSTRAINT `fk_inv_admin` FOREIGN KEY (`admin_user_id`) REFERENCES `admin_users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_inv_variant` FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `notification_queue`;
CREATE TABLE `notification_queue` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `channel` enum('email','sms') COLLATE utf8mb4_unicode_ci NOT NULL,
  `recipient` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `template_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload_json` json DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `attempts` tinyint unsigned NOT NULL DEFAULT '0',
  `scheduled_at` timestamp NULL DEFAULT NULL,
  `sent_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_notification_status_scheduled` (`status`,`scheduled_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `offer_customer_assignments`;
CREATE TABLE `offer_customer_assignments` (
  `offer_id` int unsigned NOT NULL,
  `customer_id` bigint unsigned NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`offer_id`,`customer_id`),
  KEY `fk_oca_customer` (`customer_id`),
  CONSTRAINT `fk_oca_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_oca_offer` FOREIGN KEY (`offer_id`) REFERENCES `offers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `offers`;
CREATE TABLE `offers` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'store',
  `target_id` bigint unsigned DEFAULT NULL,
  `discount_type` enum('fixed','percent') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'percent',
  `discount_value` decimal(12,2) NOT NULL,
  `max_discount` decimal(12,2) DEFAULT NULL,
  `min_cart_value` decimal(12,2) DEFAULT NULL,
  `starts_at` timestamp NULL DEFAULT NULL,
  `ends_at` timestamp NULL DEFAULT NULL,
  `priority` int NOT NULL DEFAULT '0',
  `stack_with_coupons` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_offers_active_dates` (`is_active`,`starts_at`,`ends_at`,`priority`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `order_items`;
CREATE TABLE `order_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `variant_id` bigint unsigned DEFAULT NULL,
  `product_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `variant_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sku` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` int unsigned NOT NULL,
  `unit_price` decimal(12,2) NOT NULL,
  `line_total` decimal(12,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_order_items_order` (`order_id`),
  CONSTRAINT `fk_order_items_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `order_status_history`;
CREATE TABLE `order_status_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `admin_user_id` int unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_order_status_order` (`order_id`,`created_at`),
  CONSTRAINT `fk_osh_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_number` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `order_source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'storefront',
  `subscription_delivery_day_id` bigint unsigned DEFAULT NULL,
  `customer_id` bigint unsigned DEFAULT NULL,
  `customer_address_id` bigint unsigned DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_payment',
  `subtotal` decimal(12,2) NOT NULL DEFAULT '0.00',
  `discount_total` decimal(12,2) NOT NULL DEFAULT '0.00',
  `delivery_fee` decimal(12,2) NOT NULL DEFAULT '0.00',
  `grand_total` decimal(12,2) NOT NULL DEFAULT '0.00',
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INR',
  `payment_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `delivery_slot` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_zone_id` int unsigned DEFAULT NULL,
  `delivery_slot_id` int unsigned DEFAULT NULL,
  `delivery_date` date DEFAULT NULL,
  `delivery_eta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_snapshot_json` json DEFAULT NULL,
  `coupon_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `checkout_nonce` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `placed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_orders_number` (`order_number`),
  UNIQUE KEY `uq_orders_sub_delivery_day` (`subscription_delivery_day_id`),
  KEY `idx_orders_customer_status` (`customer_id`,`status`),
  KEY `fk_orders_customer_address` (`customer_address_id`),
  CONSTRAINT `fk_orders_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_orders_customer_address` FOREIGN KEY (`customer_address_id`) REFERENCES `customer_addresses` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `payment_completion_exceptions`;
CREATE TABLE `payment_completion_exceptions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `payment_id` bigint unsigned DEFAULT NULL,
  `gateway` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gateway_payment_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gateway_order_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_event_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `captured_amount_inr` decimal(12,2) NOT NULL,
  `delivery_slot_id` int unsigned DEFAULT NULL,
  `delivery_date` date DEFAULT NULL,
  `failure_reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `failure_category` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `resolution_note` text COLLATE utf8mb4_unicode_ci,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `admin_user_id` int unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pce_gateway_payment` (`gateway`,`gateway_payment_id`),
  KEY `idx_pce_order` (`order_id`),
  KEY `idx_pce_status` (`status`),
  KEY `fk_pce_payment` (`payment_id`),
  KEY `fk_pce_slot` (`delivery_slot_id`),
  CONSTRAINT `fk_pce_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pce_payment` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_pce_slot` FOREIGN KEY (`delivery_slot_id`) REFERENCES `delivery_slots` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `payment_refunds`;
CREATE TABLE `payment_refunds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `refund_request_id` bigint unsigned DEFAULT NULL,
  `payment_id` bigint unsigned DEFAULT NULL,
  `subscription_payment_id` bigint unsigned DEFAULT NULL,
  `subscription_day_credit_id` bigint unsigned DEFAULT NULL,
  `gateway` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount_inr` decimal(12,2) NOT NULL,
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gateway_refund_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'created',
  `response_json` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payment_refunds_idempotency` (`idempotency_key`),
  UNIQUE KEY `uq_payment_refunds_gateway_refund` (`gateway`,`gateway_refund_id`),
  KEY `idx_payment_refunds_request` (`refund_request_id`),
  KEY `idx_payment_refunds_payment` (`payment_id`),
  CONSTRAINT `fk_payment_refunds_payment` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_payment_refunds_request` FOREIGN KEY (`refund_request_id`) REFERENCES `refund_requests` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `payment_webhook_events`;
CREATE TABLE `payment_webhook_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `gateway` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload_json` json NOT NULL,
  `process_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `processed_at` timestamp NULL DEFAULT NULL,
  `error_message` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_webhook_gateway_event` (`gateway`,`event_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `payments`;
CREATE TABLE `payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `gateway` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gateway_order_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_payment_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_event_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL,
  `amount_refunded_inr` decimal(12,2) NOT NULL DEFAULT '0.00',
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INR',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `metadata_json` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payments_idempotency` (`idempotency_key`),
  KEY `idx_payments_order` (`order_id`),
  KEY `idx_payments_gateway_ref` (`gateway`,`gateway_payment_id`),
  CONSTRAINT `fk_payments_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `product_attributes`;
CREATE TABLE `product_attributes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `attr_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attr_value` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_product_attributes_product` (`product_id`,`sort_order`),
  CONSTRAINT `fk_product_attributes_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `product_images`;
CREATE TABLE `product_images` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `file_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_primary` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_product_images_product` (`product_id`),
  CONSTRAINT `fk_images_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `product_related`;
CREATE TABLE `product_related` (
  `product_id` bigint unsigned NOT NULL,
  `related_product_id` bigint unsigned NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`product_id`,`related_product_id`),
  KEY `idx_product_related_related` (`related_product_id`),
  CONSTRAINT `fk_product_related_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_product_related_related` FOREIGN KEY (`related_product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `product_review_photos`;
CREATE TABLE `product_review_photos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `review_id` bigint unsigned NOT NULL,
  `file_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_review_photos_review` (`review_id`),
  CONSTRAINT `fk_review_photos_review` FOREIGN KEY (`review_id`) REFERENCES `product_reviews` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `product_reviews`;
CREATE TABLE `product_reviews` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `customer_id` bigint unsigned NOT NULL,
  `display_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `order_id` bigint unsigned DEFAULT NULL,
  `order_item_id` bigint unsigned DEFAULT NULL,
  `rating` tinyint unsigned NOT NULL,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body` text COLLATE utf8mb4_unicode_ci,
  `verified_purchase` tinyint(1) NOT NULL DEFAULT '0',
  `sub_ratings_json` json DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `admin_reply` text COLLATE utf8mb4_unicode_ci,
  `admin_reply_at` timestamp NULL DEFAULT NULL,
  `admin_reply_by` int unsigned DEFAULT NULL,
  `rejection_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `featured` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reviews_order_item` (`order_item_id`),
  KEY `idx_reviews_product_status` (`product_id`,`status`),
  KEY `fk_reviews_customer` (`customer_id`),
  CONSTRAINT `fk_reviews_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_reviews_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `product_variants`;
CREATE TABLE `product_variants` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sku` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `weight_kg` decimal(8,3) DEFAULT NULL,
  `price` decimal(12,2) NOT NULL,
  `sale_price` decimal(12,2) DEFAULT NULL,
  `stock_qty` int NOT NULL DEFAULT '0',
  `low_stock_threshold` int NOT NULL DEFAULT '5',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_variant_sku` (`sku`),
  KEY `idx_variants_product` (`product_id`),
  CONSTRAINT `fk_variants_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int unsigned DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sku` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `short_description` text COLLATE utf8mb4_unicode_ci,
  `description` longtext COLLATE utf8mb4_unicode_ci,
  `product_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'fresh',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `is_bestseller` tinyint(1) NOT NULL DEFAULT '0',
  `is_new_arrival` tinyint(1) NOT NULL DEFAULT '0',
  `grants_free_delivery` tinyint(1) NOT NULL DEFAULT '0',
  `meta_title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `robots_index` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_products_slug` (`slug`),
  KEY `idx_products_category_status` (`category_id`,`status`),
  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `refund_request_evidence`;
CREATE TABLE `refund_request_evidence` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `refund_request_id` bigint unsigned NOT NULL,
  `file_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mime_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_refund_evidence_request` (`refund_request_id`),
  CONSTRAINT `fk_refund_evidence_request` FOREIGN KEY (`refund_request_id`) REFERENCES `refund_requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `refund_request_history`;
CREATE TABLE `refund_request_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `refund_request_id` bigint unsigned NOT NULL,
  `actor_type` enum('customer','admin','system') COLLATE utf8mb4_unicode_ci NOT NULL,
  `actor_id` bigint unsigned DEFAULT NULL,
  `action` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload_json` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_refund_history_request` (`refund_request_id`,`created_at`),
  CONSTRAINT `fk_refund_history_request` FOREIGN KEY (`refund_request_id`) REFERENCES `refund_requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `refund_request_items`;
CREATE TABLE `refund_request_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `refund_request_id` bigint unsigned NOT NULL,
  `order_item_id` bigint unsigned NOT NULL,
  `quantity` int unsigned NOT NULL,
  `amount_inr` decimal(12,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_refund_items_request` (`refund_request_id`),
  KEY `fk_refund_items_order_item` (`order_item_id`),
  CONSTRAINT `fk_refund_items_order_item` FOREIGN KEY (`order_item_id`) REFERENCES `order_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_refund_items_request` FOREIGN KEY (`refund_request_id`) REFERENCES `refund_requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `refund_requests`;
CREATE TABLE `refund_requests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `request_number` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_id` bigint unsigned NOT NULL,
  `order_id` bigint unsigned NOT NULL,
  `support_ticket_id` bigint unsigned DEFAULT NULL,
  `reason_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `preferred_resolution` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'refund',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'requested',
  `approved_amount_inr` decimal(12,2) DEFAULT NULL,
  `rejection_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `internal_notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_refund_request_number` (`request_number`),
  KEY `idx_refund_requests_status` (`status`,`created_at`),
  KEY `idx_refund_requests_order` (`order_id`),
  KEY `fk_refund_req_customer` (`customer_id`),
  CONSTRAINT `fk_refund_req_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_refund_req_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `seo_redirects`;
CREATE TABLE `seo_redirects` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `from_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `to_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `http_code` smallint NOT NULL DEFAULT '301',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_seo_from` (`from_path`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `setting_key` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `setting_value` text COLLATE utf8mb4_unicode_ci,
  `is_encrypted` tinyint(1) NOT NULL DEFAULT '0',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_settings_key` (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_auto_confirm_events`;
CREATE TABLE `subscription_auto_confirm_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subscription_delivery_day_id` bigint unsigned NOT NULL,
  `basket_id` bigint unsigned DEFAULT NULL,
  `cron_run_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `confirmed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_auto_confirm_day` (`subscription_delivery_day_id`),
  CONSTRAINT `fk_sace_day` FOREIGN KEY (`subscription_delivery_day_id`) REFERENCES `subscription_delivery_days` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_basket_substitutions`;
CREATE TABLE `subscription_basket_substitutions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subscription_delivery_day_id` bigint unsigned NOT NULL,
  `original_variant_id` bigint unsigned NOT NULL,
  `original_qty` decimal(10,3) NOT NULL,
  `original_unit_price_inr` decimal(12,2) NOT NULL,
  `proposed_variant_id` bigint unsigned NOT NULL,
  `proposed_qty` decimal(10,3) NOT NULL,
  `proposed_unit_price_inr` decimal(12,2) NOT NULL,
  `price_difference_inr` decimal(12,2) NOT NULL DEFAULT '0.00',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_customer',
  `customer_decision_at` timestamp NULL DEFAULT NULL,
  `admin_user_id` int unsigned DEFAULT NULL,
  `admin_note` text COLLATE utf8mb4_unicode_ci,
  `substitution_payment_id` bigint unsigned DEFAULT NULL,
  `rejection_resolution` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sub_substitution_day` (`subscription_delivery_day_id`,`status`),
  CONSTRAINT `fk_sbs_day` FOREIGN KEY (`subscription_delivery_day_id`) REFERENCES `subscription_delivery_days` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_customer_preferences`;
CREATE TABLE `subscription_customer_preferences` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` bigint unsigned NOT NULL,
  `variant_id` bigint unsigned NOT NULL,
  `preference` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'prefer' COMMENT 'prefer|avoid',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sub_pref_customer_variant` (`customer_id`,`variant_id`),
  KEY `fk_scp_variant` (`variant_id`),
  CONSTRAINT `fk_scp_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_scp_variant` FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_day_credits`;
CREATE TABLE `subscription_day_credits` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subscription_delivery_day_id` bigint unsigned NOT NULL,
  `customer_subscription_id` bigint unsigned NOT NULL,
  `credit_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'delivery_entitlement|refund_pending|refund_completed',
  `amount_inr` decimal(12,2) NOT NULL DEFAULT '0.00',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'applied',
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `parent_subscription_payment_id` bigint unsigned DEFAULT NULL,
  `gateway_refund_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_refund_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_refund_requested_at` timestamp NULL DEFAULT NULL,
  `gateway_refund_completed_at` timestamp NULL DEFAULT NULL,
  `detail_json` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sub_day_credit_day` (`subscription_delivery_day_id`),
  UNIQUE KEY `uq_sub_day_credit_idempotency` (`idempotency_key`),
  KEY `fk_sdc_sub` (`customer_subscription_id`),
  CONSTRAINT `fk_sdc_day` FOREIGN KEY (`subscription_delivery_day_id`) REFERENCES `subscription_delivery_days` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_sdc_sub` FOREIGN KEY (`customer_subscription_id`) REFERENCES `customer_subscriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_delivery_basket_items`;
CREATE TABLE `subscription_delivery_basket_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `basket_id` bigint unsigned NOT NULL,
  `variant_id` bigint unsigned NOT NULL,
  `product_name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `variant_name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unit_label` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `qty` decimal(10,3) NOT NULL,
  `unit_price_inr` decimal(12,2) NOT NULL,
  `line_total_inr` decimal(12,2) NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_basket_items_basket` (`basket_id`,`sort_order`),
  CONSTRAINT `fk_sdbi_basket` FOREIGN KEY (`basket_id`) REFERENCES `subscription_delivery_baskets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_delivery_baskets`;
CREATE TABLE `subscription_delivery_baskets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subscription_delivery_day_id` bigint unsigned NOT NULL,
  `source_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'suggested' COMMENT 'suggested|custom',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'suggested|draft|confirmed',
  `allowance_inr` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total_inr` decimal(12,2) NOT NULL DEFAULT '0.00',
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_delivery_basket_day` (`subscription_delivery_day_id`),
  CONSTRAINT `fk_sdb_day` FOREIGN KEY (`subscription_delivery_day_id`) REFERENCES `subscription_delivery_days` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_delivery_days`;
CREATE TABLE `subscription_delivery_days` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_subscription_id` bigint unsigned NOT NULL,
  `delivery_date` date NOT NULL,
  `day_index` int unsigned NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled',
  `selection_cutoff_at` datetime DEFAULT NULL,
  `basket_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `fulfilment_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `generated_order_id` bigint unsigned DEFAULT NULL,
  `preferred_delivery_slot_slug` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `preferred_delivery_slot_id` int unsigned DEFAULT NULL,
  `slot_snapshot_json` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sub_delivery_day` (`customer_subscription_id`,`delivery_date`),
  KEY `idx_sub_delivery_days_sub` (`customer_subscription_id`,`day_index`),
  CONSTRAINT `fk_sdd_sub` FOREIGN KEY (`customer_subscription_id`) REFERENCES `customer_subscriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_delivery_entitlement_events`;
CREATE TABLE `subscription_delivery_entitlement_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subscription_delivery_day_id` bigint unsigned NOT NULL,
  `delivery_id` bigint unsigned NOT NULL,
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sub_entitlement_day` (`subscription_delivery_day_id`),
  UNIQUE KEY `uq_sub_entitlement_delivery` (`delivery_id`),
  UNIQUE KEY `uq_sub_entitlement_idempotency` (`idempotency_key`),
  CONSTRAINT `fk_sdee_day` FOREIGN KEY (`subscription_delivery_day_id`) REFERENCES `subscription_delivery_days` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_fulfilment_events`;
CREATE TABLE `subscription_fulfilment_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subscription_delivery_day_id` bigint unsigned NOT NULL,
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cron_run_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `order_id` bigint unsigned DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sub_fulfilment_day` (`subscription_delivery_day_id`),
  UNIQUE KEY `uq_sub_fulfilment_idempotency` (`idempotency_key`),
  CONSTRAINT `fk_sfe_day` FOREIGN KEY (`subscription_delivery_day_id`) REFERENCES `subscription_delivery_days` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_menu_template_items`;
CREATE TABLE `subscription_menu_template_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `menu_template_id` int unsigned NOT NULL,
  `variant_id` bigint unsigned NOT NULL,
  `default_qty` decimal(10,3) NOT NULL DEFAULT '1.000',
  `unit_label` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'kg',
  `unit_price_inr` decimal(12,2) NOT NULL,
  `include_in_rotation` tinyint(1) NOT NULL DEFAULT '1',
  `max_qty` decimal(10,3) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_menu_item_variant` (`menu_template_id`,`variant_id`),
  KEY `idx_menu_items_template` (`menu_template_id`,`sort_order`),
  KEY `fk_smti_variant` (`variant_id`),
  CONSTRAINT `fk_smti_template` FOREIGN KEY (`menu_template_id`) REFERENCES `subscription_menu_templates` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_smti_variant` FOREIGN KEY (`variant_id`) REFERENCES `product_variants` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_menu_templates`;
CREATE TABLE `subscription_menu_templates` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `planner_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'date|weekly|day_index',
  `template_date` date DEFAULT NULL,
  `weekday` tinyint unsigned DEFAULT NULL COMMENT '1=Mon..7=Sun',
  `day_index` int unsigned DEFAULT NULL COMMENT '1-based plan delivery index',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_menu_templates_lookup` (`planner_type`,`template_date`,`weekday`,`day_index`),
  KEY `idx_menu_templates_active` (`is_active`,`planner_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_notification_log`;
CREATE TABLE `subscription_notification_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` bigint unsigned NOT NULL,
  `notification_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sub_notification_dedupe` (`notification_type`,`reference_key`),
  KEY `fk_snl_customer` (`customer_id`),
  CONSTRAINT `fk_snl_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_pauses`;
CREATE TABLE `subscription_pauses` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_subscription_id` bigint unsigned NOT NULL,
  `paused_at` timestamp NOT NULL,
  `resumed_at` timestamp NULL DEFAULT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `note` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_pauses_sub` (`customer_subscription_id`,`status`),
  CONSTRAINT `fk_pause_sub` FOREIGN KEY (`customer_subscription_id`) REFERENCES `customer_subscriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_payments`;
CREATE TABLE `subscription_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_subscription_id` bigint unsigned NOT NULL,
  `gateway` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gateway_order_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_payment_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_event_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL,
  `amount_refunded_inr` decimal(12,2) NOT NULL DEFAULT '0.00',
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INR',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'created',
  `idempotency_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `metadata_json` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_subscription_payments_idempotency` (`idempotency_key`),
  KEY `idx_subscription_payments_sub` (`customer_subscription_id`),
  KEY `idx_subscription_payments_gateway` (`gateway`,`gateway_order_id`),
  CONSTRAINT `fk_spay_sub` FOREIGN KEY (`customer_subscription_id`) REFERENCES `customer_subscriptions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_plan_audit`;
CREATE TABLE `subscription_plan_audit` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `subscription_plan_id` int unsigned NOT NULL,
  `admin_user_id` int unsigned DEFAULT NULL,
  `action` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_subscription_plan_audit_plan` (`subscription_plan_id`,`created_at`),
  CONSTRAINT `fk_spa_plan` FOREIGN KEY (`subscription_plan_id`) REFERENCES `subscription_plans` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_plans`;
CREATE TABLE `subscription_plans` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `internal_notes` text COLLATE utf8mb4_unicode_ci,
  `calendar_duration_days` int unsigned NOT NULL,
  `delivery_count` int unsigned NOT NULL,
  `duration_model` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'hybrid',
  `frequency_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'daily',
  `frequency_config` json DEFAULT NULL,
  `basket_rules_json` json NOT NULL,
  `price` decimal(12,2) NOT NULL,
  `compare_at_price` decimal(12,2) DEFAULT NULL,
  `payment_rules_json` json DEFAULT NULL,
  `skip_pause_policy_json` json DEFAULT NULL,
  `slot_policy_json` json DEFAULT NULL,
  `selection_cutoff_hours` int unsigned NOT NULL DEFAULT '18',
  `is_active` tinyint(1) NOT NULL DEFAULT '0',
  `is_default_template` tinyint(1) NOT NULL DEFAULT '0',
  `template_key` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_subscription_plans_template_key` (`template_key`),
  KEY `idx_subscription_plans_active` (`is_active`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `subscription_recovery_log`;
